    register: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": {
                    admin: {
                        /**
                         * Format: email
                         * @description Admin email address
                         * @example admin@example.com
                         */
                        email: string;
                        /**
                         * @description Admin full name
                         * @example John Doe
                         */
                        name: string;
                        /**
                         * Format: password
                         * @description Password must contain:
                         *     - At least 8 characters
                         *     - Upper and lowercase letters
                         *     - At least one number
                         *     - At least one special character
                         * @example SecurePass123!
                         */
                        password: string;
                        /**
                         * @description Password confirmation (must match password)
                         * @example SecurePass123!
                         */
                        password_confirmation: string;
                    };
                    organization: {
                        /**
                         * @description Organization name (must be unique)
                         * @example Acme Corporation
                         */
                        name: string;
                        /**
                         * @description URL-friendly slug, must be unique (generated from the name when empty or omitted)
                         * @example acme-corporation
                         */
                        slug?: string | null;
                        /**
                         * @description Organization timezone (any PHP timezone identifier)
                         * @example America/New_York
                         */
                        timezone: string;
                    };
                    /** @description Optional reCAPTCHA v3 token. Verified when reCAPTCHA is enabled and the token is sent; omitting it skips the check. */
                    recaptcha_token?: string | null;
                };
            };
        };
        responses: {
            /** @description Organization registered successfully */
            201: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "message": "Organization registered successfully",
                     *       "user": {
                     *         "id": 123,
                     *         "organization_id": 1,
                     *         "name": "John Doe",
                     *         "email": "admin@example.com",
                     *         "role": "owner",
                     *         "status": "active"
                     *       },
                     *       "organization": {
                     *         "id": 1,
                     *         "name": "Acme Corporation",
                     *         "slug": "acme-corporation",
                     *         "status": "active",
                     *         "timezone": "America/New_York"
                     *       },
                     *       "access_token": "1|laravel_sanctum_token_xyz123",
                     *       "token_type": "Bearer",
                     *       "expires_in": 86400
                     *     }
                     */
                    "application/json": {
                        /**
                         * @description Bearer token for immediate access
                         * @example 1|laravel_sanctum_token_xyz123
                         */
                        access_token?: string;
                        /**
                         * @description Token expiration in seconds (24 hours)
                         * @example 86400
                         */
                        expires_in?: number;
                        /** @example Organization registered successfully */
                        message?: string;
                        /** @description The new organization */
                        organization?: {
                            id?: number;
                            name?: string;
                            slug?: string;
                            /** @example active */
                            status?: string;
                            timezone?: string;
                        };
                        /** @example Bearer */
                        token_type?: string;
                        /** @description The new owner user */
                        user?: {
                            /** Format: email */
                            email?: string;
                            id?: number;
                            name?: string;
                            organization_id?: number;
                            /** @enum {string} */
                            role?: "owner";
                            /** @enum {string} */
                            status?: "active";
                        };
                    };
                };
            };
            422: components["responses"]["ValidationError"];
            /** @description Too many registration attempts */
            429: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "error": {
                     *         "code": "RATE_LIMIT_EXCEEDED",
                     *         "message": "Too many registration attempts. Please try again in 1 hour.",
                     *         "retry_after": 3600
                     *       }
                     *     }
                     */
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description Registration failed */
            500: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "error": {
                     *         "code": "REGISTRATION_FAILED",
                     *         "message": "An error occurred during registration. Please try again."
                     *       }
                     *     }
                     */
                    "application/json": components["schemas"]["Error"];
                };
            };
        };
    };
