                            /**
                             * @description Null when the DID no longer exists
                             * @example +12127773456
                             */
                            phone_number?: string | null;
                            /**
                             * @description completed_calls / total_calls x 100, two decimals (0 when no calls)
                             * @example 90
                             */
                            success_rate?: number;
                            /** @example 50 */
